# Make target mask of 2s in left 15x7 and piece placements with fixed orientation
mask={(r,c) for r in range(15) for c in range(7) if testgrid[r][c]==2}
pieces=[('6a',6,1,4),('6b',6,1,4),('7',7,3,2),('4',4,6,2),('8',8,2,2),('1',1,2,5),('0',0,1,1)]
placements={}
for name,color,h,w in pieces:
 pp=[]
 for r in range(15-h+1):
  for c in range(7-w+1):
   cells={(rr,cc) for rr in range(r,r+h) for cc in range(c,c+w)}
   if cells<=mask: pp.append((r,c,cells))
 placements[name]=pp
print('mask',len(mask), {k:len(v) for k,v in placements.items()})
# backtracking exact cover by piece placements, select next uncovered cell with fewest possible placements
sols=[]
def solve(remnames, uncovered, chosen):
 if not remnames:
  if not uncovered: sols.append(chosen.copy())
  return
 # choose cell constrained among all compatible placement candidates
 candidates_by_cell={}
 for cell in uncovered:
  cc=[]
  for name in remnames:
   for r,c,cells in placements[name]:
    if cell in cells and cells<=uncovered: cc.append((name,r,c,cells))
  candidates_by_cell[cell]=cc
 cell=min(uncovered,key=lambda x:len(candidates_by_cell[x]))
 for name,r,c,cells in candidates_by_cell[cell]:
  if len(sols)>=10000:return
  solve([n for n in remnames if n!=name],uncovered-cells,chosen+[(name,r,c,cells)])
solve([p[0] for p in pieces],mask,[])
print('solutions',len(sols))
for s in sols[:3]: print([(n,r,c) for n,r,c,_ in s])
